// Some portions generated by Claude
// Parts that share no link stay a component gap apart, so whitespace says what is not connected; orphans are gathered
// into one grid per type.
import assert from 'node:assert/strict';
import test from 'node:test';
import { computeGraphLayout } from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import { LAYOUT_SPACING } from '../../../main/frontend/graph-explorer/graph-layout-spacing.ts';
import { ARROW_LENGTH } from '../../../main/frontend/graph-explorer/graph-layout-organic.ts';
import { graphNodeSize } from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import { expansionMovableIds } from '../../../main/frontend/graph-explorer/graph-layout-expansion.ts';
import { seedIncrementalNodes } from '../../../main/frontend/graph-explorer/graph-operations.ts';

const typeA = { id: 'urn:TypeA', label: 'Type A' };
const typeB = { id: 'urn:TypeB', label: 'Type B' };
const iri = (id, label, types) => ({ id, label, kind: 'iri', ...(types ? { types } : {}) });
const link = (source, target) => ({ id: `${source}->${target}`, source, target, predicate: 'urn:p', label: 'p' });

/** A three-card chain, a five-leaf star, three orphans of type A, two of type B and an orphan literal. */
function mixedGraph() {
  const nodes = [
    iri('c0', 'Chain 0'), iri('c1', 'Chain 1'), iri('c2', 'Chain 2'),
    iri('s0', 'Star hub'), ...[1, 2, 3, 4, 5].map((i) => iri(`s${i}`, `Star leaf ${i}`)),
    iri('a0', 'Alpha one', [typeA]), iri('a1', 'Alpha two', [typeA]), iri('a2', 'Alpha three', [typeA]),
    iri('b0', 'Beta one', [typeB]), iri('b1', 'Beta two', [typeB]),
    { id: '"42"', label: '42', kind: 'literal' },
  ];
  const edges = [link('c0', 'c1'), link('c1', 'c2'), ...[1, 2, 3, 4, 5].map((i) => link('s0', `s${i}`))];
  return { nodes, edges, revision: 1 };
}

/** Card index of the connected component each card belongs to. */
function componentOf(graph) {
  const parent = new Map(graph.nodes.map((n) => [n.id, n.id]));
  const find = (id) => (parent.get(id) === id ? id : find(parent.get(id)));
  for (const e of graph.edges) parent.set(find(e.source), find(e.target));
  return new Map(graph.nodes.map((n) => [n.id, find(n.id)]));
}

/** Gap between two card boxes along the axis that separates them most (negative when they overlap). */
function boxGap(graph, positions, a, b) {
  const na = graph.nodes.find((n) => n.id === a), nb = graph.nodes.find((n) => n.id === b);
  const pa = positions.get(a), pb = positions.get(b), sa = graphNodeSize(na), sb = graphNodeSize(nb);
  return Math.max(Math.abs(pa.x - pb.x) - (sa.width + sb.width) / 2, Math.abs(pa.y - pb.y) - (sa.height + sb.height) / 2);
}

const isOrphan = (graph, id) => !graph.edges.some((e) => e.source === id || e.target === id);

test('organize keeps cards a component gap from every part they share no link with', async () => {
  const graph = mixedGraph();
  const result = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 1.6 });
  const component = componentOf(graph);
  const gaps = [];
  for (const a of graph.nodes) for (const b of graph.nodes) {
    if (a.id >= b.id || component.get(a.id) === component.get(b.id)) continue;
    if (isOrphan(graph, a.id) && isOrphan(graph, b.id)) continue;
    gaps.push({ pair: `${a.id}/${b.id}`, gap: boxGap(graph, result.positions, a.id, b.id) });
  }
  const closest = gaps.sort((x, y) => x.gap - y.gap)[0];
  assert.ok(LAYOUT_SPACING.componentGap > 2 * ARROW_LENGTH, 'unlinked parts sit clearly further apart than linked cards');
  assert.ok(closest.gap >= LAYOUT_SPACING.componentGap - 0.5,
    `unlinked cards ${closest.pair} are ${closest.gap.toFixed(0)} px apart (want ${LAYOUT_SPACING.componentGap})`);
});

test('organize gathers orphans into one grid per type', async () => {
  const graph = mixedGraph();
  const result = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 1.6 });
  const groups = { A: ['a0', 'a1', 'a2'], B: ['b0', 'b1'], literal: ['"42"'] };
  const boxes = Object.fromEntries(Object.entries(groups).map(([key, ids]) => {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const id of ids) {
      const p = result.positions.get(id), s = graphNodeSize(graph.nodes.find((n) => n.id === id));
      minX = Math.min(minX, p.x - s.width / 2); maxX = Math.max(maxX, p.x + s.width / 2);
      minY = Math.min(minY, p.y - s.height / 2); maxY = Math.max(maxY, p.y + s.height / 2);
    }
    return [key, { minX, minY, maxX, maxY }];
  }));
  const keys = Object.keys(groups);
  for (const a of keys) for (const b of keys) {
    if (a >= b) continue;
    const x = boxes[a], y = boxes[b];
    assert.ok(x.maxX <= y.minX || y.maxX <= x.minX || x.maxY <= y.minY || y.maxY <= x.minY, `the ${a} and ${b} orphan grids overlap`);
  }
  for (const [key, ids] of Object.entries(groups)) {
    if (ids.length < 2) continue;
    for (const id of ids) {
      const p = result.positions.get(id);
      const others = ids.filter((other) => other !== id);
      assert.ok(others.some((other) => Math.abs(result.positions.get(other).x - p.x) < 0.5 || Math.abs(result.positions.get(other).y - p.y) < 0.5),
        `${id} shares neither a row nor a column with the other ${key} orphans`);
      const nearest = Math.min(...others.map((other) => boxGap(graph, result.positions, id, other)));
      assert.ok(nearest < LAYOUT_SPACING.groupGap, `${id} is ${nearest.toFixed(0)} px from the nearest ${key} orphan`);
    }
  }
});

test('cards added without a link into the drawing land a component gap away from it', async () => {
  const graph = mixedGraph();
  const shown = new Set(['c0', 'c1', 'c2', 's0', 's1', 's2', 's3', 's4', 's5']);
  const first = await computeGraphLayout({ nodes: graph.nodes.filter((n) => shown.has(n.id)), edges: graph.edges, revision: 1 },
    { mode: 'network', aspectRatio: 1.6 });
  // Expanding c2 brings a new leaf linked to it, a new orphan and a new linked pair that touches nothing drawn.
  const added = [iri('c3', 'Chain 3'), iri('n0', 'New orphan', [typeA]), iri('p0', 'Pair one'), iri('p1', 'Pair two')];
  const nodes = [...graph.nodes.filter((n) => shown.has(n.id)).map((n) => ({ ...n, ...first.positions.get(n.id) })), ...added];
  const edges = [...graph.edges, link('c2', 'c3'), link('p0', 'p1')];
  const fresh = new Set(added.map((n) => n.id));
  const seeded = seedIncrementalNodes({ nodes, edges, revision: 2 }, shown, ['c2']);
  const movable = expansionMovableIds(seeded.nodes, seeded.edges, 'c2', fresh);
  const result = await computeGraphLayout(seeded, { mode: 'network', aspectRatio: 1.6, incremental: true, movableNodeIds: movable, newNodeIds: fresh });
  for (const n of seeded.nodes) if (!movable.has(n.id)) assert.deepEqual(result.positions.get(n.id), { x: n.x, y: n.y }, `${n.label} moved`);
  const component = componentOf(seeded);
  for (const id of ['n0', 'p0', 'p1']) for (const other of seeded.nodes) {
    if (component.get(other.id) === component.get(id)) continue;
    const gap = boxGap(seeded, result.positions, id, other.id);
    assert.ok(gap >= LAYOUT_SPACING.componentGap - 0.5, `new ${id} is ${gap.toFixed(0)} px from ${other.id}`);
  }
  assert.ok(boxGap(seeded, result.positions, 'p0', 'p1') <= 2 * ARROW_LENGTH, 'the new linked pair stays together');
  assert.ok(boxGap(seeded, result.positions, 'c2', 'c3') <= 2 * ARROW_LENGTH, 'the new leaf stays beside the card it links to');
});
